// Klikchart Commerce v4.7 — unified UX, safer dialogs, responsive account and checkout.
const S={me:null,view:'',data:{},categories:[],q:'',sort:'new',category:'',page:1,orderPage:1,sellerPage:1,ownerProductPage:1,productId:null,shopId:null,activePhoto:0,minPrice:'',maxPrice:'',busy:false,site:null,userPage:1,shopPage:1,epoch:0,theme:'light',themeFetched:false,accountTab:'info',pendingContact:null,profileSnapshot:null};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rup=n=>'Rp '+new Intl.NumberFormat('id-ID').format(Number(n)||0);
const fmt=d=>{try{return new Date(d).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})}catch{return '—'}};
const pic=p=>p?.image_url?`<span class="product-image-frame"><span class="product-image-fallback" aria-hidden="true">${ico("package")}</span><img loading="lazy" decoding="async" alt="${E(p.name||'Foto produk')}" src="${E(p.image_url)}" referrerpolicy="no-referrer"></span>`:'<span class="art" aria-hidden="true">'+ico('package')+'</span>';
const money=n=>rup(n);
const badge=s=>{const labels={pending:'Menunggu',approved:'Disetujui',rejected:'Ditolak',accepted:'Diterima',packed:'Dikemas',shipped:'Dikirim',delivered:'Selesai',canceled:'Dibatalkan',published:'Tayang',draft:'Draft',archived:'Diarsipkan',active:'Aktif',suspended:'Ditangguhkan'};const tone=['approved','delivered','published','active'].includes(s)?'green':['pending','accepted','packed','shipped'].includes(s)?'orange':['rejected','canceled','suspended'].includes(s)?'red':'gray';return `<span class="status ${tone}">${E(labels[s]||s)}</span>`};
const empty=(title,text='Belum ada data untuk ditampilkan.')=>`<div class="empty"><span>${ico("sparkle")}</span><b>${E(title)}</b><small>${E(text)}</small></div>`;
const btn=(label,action,opts='')=>`<button type="button" class="btn ${opts}" data-action="${action}">${label}</button>`;
const productPager=(info,prefix)=>Number(info?.total||0)>20?
 `<div class="tools" style="margin-top:18px">${btn('← Sebelumnya',prefix+'-prev','small')}<span class="hint">Halaman ${Number(info.page)||1} dari ${Math.max(1,Math.ceil(Number(info.total||0)/20))}</span>${btn('Berikutnya →',prefix+'-next','small')}</div>`:'';
const panel=(title,body,aside='')=>`<section class="panel"><div class="panel-heading"><h2>${title}</h2>${aside}</div>${body}</section>`;
const metric=(label,value,icon,foot='Data aktual')=>`<div class="kpi"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon}</span></div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div></div>`;
let toastTimer;function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200)}
function msg(e){const codes={UNAUTHORIZED:'Silakan masuk terlebih dahulu.',PASSWORD_CURRENT_REQUIRED:'Masukkan kata sandi saat ini.',PASSWORD_CURRENT_INVALID:'Kata sandi saat ini salah.',PASSWORD_UNCHANGED:'Buat kata sandi baru yang berbeda.',PASSWORD_UPDATE_FAILED:'Gagal menyimpan kata sandi di penyedia autentikasi.',USERNAME_INVALID:'Nama pengguna harus 3–20 karakter (huruf, angka, titik atau garis bawah).',USERNAME_TAKEN:'Nama pengguna sudah dipakai.',ROLE_FORBIDDEN:'Akses tidak diizinkan untuk peran akun ini.',SELLER_CONTACTS_REQUIRED:'Aktifkan Email dan WhatsApp di Akun & Pengaturan sebelum mengajukan toko.',APPLICATION_PENDING:'Pengajuanmu masih menunggu pemeriksaan owner.',ALREADY_SELLER:'Akun sudah memiliki akses penjual.',OUT_OF_STOCK:'Stok tidak cukup, periksa kembali keranjang.',PRODUCT_UNAVAILABLE:'Produk sudah tidak tersedia.',SHOP_UNAVAILABLE:'Toko tidak tersedia.',SHOP_SUSPENDED:'Toko sementara ditangguhkan.',CART_EMPTY:'Keranjang masih kosong.',ADDRESS_INVALID:'Alamat pengiriman tidak ditemukan.',PURCHASE_REQUIRED:'Ulasan hanya untuk produk yang sudah diterima.',TRANSITION_FORBIDDEN:'Perubahan status pesanan tidak diizinkan.',DATABASE_ERROR:'Database belum siap. Pastikan SQL migration 008 sudah dijalankan.',IMAGE_SIZE_INVALID:'Ukuran foto maksimal 2 MB.',IMAGE_TYPE_INVALID:'Format foto harus PNG, JPEG, atau WebP.',IMAGE_UPLOAD_FAILED:'Unggahan foto gagal. Silakan coba kembali.',NETWORK_ERROR:'Jaringan terputus atau server tidak merespons.',RATE_LIMITED:'Terlalu banyak permintaan. Coba lagi nanti.',VALIDATION_ERROR:'Isi data dengan benar dan lengkap.',OTP_INVALID:'Kode OTP salah atau kedaluwarsa.',CHANNEL_UNAVAILABLE:'Layanan OTP belum tersedia.',SMTP_AUTH_FAILED:'Gagal autentikasi email pengirim.',DELIVERY_FAILED:'Pengiriman OTP gagal. Periksa pengaturan layanan.',ALREADY_VERIFIED:'Kontak ini sudah aktif.',RESEND_WAIT:'Tunggu 60 detik sebelum meminta OTP baru.',FORBIDDEN:'Permintaan ditolak. Periksa APP_URL di .env.',NOT_FOUND:'Data tidak ditemukan.'};return codes[e?.code]||e?.code||e?.message||'Terjadi masalah.'}
async function api(path,data){const request={credentials:'same-origin',cache:'no-store',method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-Klikchart-Request':'1'},...(data===undefined?{}:{body:JSON.stringify(data)})};const r=await fetch('/api/market/'+path,request);let json;try{json=await r.json()}catch{throw Error('Respons server tidak valid')};if(!r.ok||!json.ok){throw Object.assign(Error(json?.error?.code||'NETWORK_ERROR'),{code:json?.error?.code||'NETWORK_ERROR'})}return json.data}

async function accountAPI(path,body){const response=await fetch('/api/account/'+path,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Klikchart-Request':'1'},body:JSON.stringify(body||{})});const result=await response.json();if(!response.ok||!result.ok)throw Object.assign(Error(result?.error?.code||'OTP_FAILED'),{code:result?.error?.code||'OTP_FAILED'});return result.data;}
const isLogged=()=>!!S.me;const role=()=>S.me?.role||'visitor';const who=()=>S.me?.user?.username||'Pengunjung';
const displayWho=()=>S.profileSnapshot?.settings?.display_name?.trim()||who();
const roleLabel=()=>role()==='owner'?'Owner aplikasi':role()==='seller'?'Penjual':'Pembeli';
const avatarMarkup=(extra='')=>{const url=S.profileSnapshot?.settings?.avatar_url;return `<span class="avatar ${extra}">${url?`<img src="${E(url)}" alt="" loading="lazy" decoding="async">`:''}<span class="avatar-initial">${E(displayWho().charAt(0).toUpperCase()||'K')}</span></span>`};
const profilePopup=()=>`<div class="profile-menu-host"><button type="button" class="profile-menu-toggle" data-action="profile-menu-toggle" aria-controls="profile-menu" aria-expanded="false" aria-haspopup="true" aria-label="Buka menu akun ${E(displayWho())}">${avatarMarkup('profile-top-avatar')}<span class="profile-menu-label"><strong>${E(displayWho())}</strong><small>${E(roleLabel())}</small></span><span class="profile-chevron" aria-hidden="true">⌄</span></button><div id="profile-menu" class="profile-menu" hidden><div class="profile-menu-heading">${avatarMarkup('profile-menu-avatar')}<span><strong>${E(displayWho())}</strong><small>${E(S.me?.user?.email||roleLabel())}</small></span></div><div class="profile-menu-divider"></div><a href="#account" class="profile-menu-item">${ico('account')}<span>Profil & akun<small>Identitas dan data pribadi</small></span></a><button type="button" class="profile-menu-item" data-action="account-shortcut:security">${ico('ownerSettings')}<span>Keamanan akun<small>Sandi dan verifikasi kontak</small></span></button><button type="button" class="profile-menu-item" data-action="account-shortcut:preferences">${ico('categories')}<span>Tampilan & notifikasi<small>Sesuaikan preferensi</small></span></button><a href="${role()==='owner'?'#ownerOrders':role()==='seller'?'#sellerOrders':'#orders'}" class="profile-menu-item">${ico('orders')}<span>${role()==='owner'?'Pesanan marketplace':role()==='seller'?'Pesanan toko':'Pesanan saya'}</span></a><div class="profile-menu-divider"></div><button type="button" class="profile-menu-item profile-menu-logout" data-action="logout">${ico("logout")} <span>Keluar dari akun</span></button></div></div>`;
