const ico=key=>`<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]||icons.home}</svg>`;
const logo=`<svg class="kc-logo" viewBox="0 0 32 32" width="30" height="30" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 11h16l1.2 17H6.8L8 11z"/><path d="M12 12V9a4 4 0 0 1 8 0v3"/><path d="M12 21q4 5 8 0"/></svg>`;
const groups=()=>role()==='owner' ? [
 [['ownerHome','Ringkasan'],['ownerOrders','Pesanan'],['ownerProducts','Produk'],['ownerShops','Toko']],
 [['ownerApplications','Pengajuan penjual'],['ownerUsers','Pengguna'],['categories','Kategori'],['ownerSettings','Pengaturan web']]
] : role()==='seller' ? [
 [['sellerHome','Ringkasan'],['sellerOrders','Pesanan masuk'],['sellerProducts','Produk toko'],['sellerShop','Informasi toko']]
] : [[['home','Beranda'],['orders','Pesanan saya'],['cart','Keranjang'],['wishlist','Favorit']]];
const start=()=>role()==='owner'?'ownerHome':role()==='seller'?'sellerHome':'home';
const shoppingViews=new Set(['home','shop','product','cart','wishlist','orders','addresses']);
const isStore=()=>shoppingViews.has(S.view)||(role()==='buyer'&&['account','apply'].includes(S.view));
function storeLayout(inner){
 const cartLink=isLogged()?'#cart':'/login';
 const quickLink=isLogged()?'#account':'/login';
 const roleLink=role()==='owner'?'#ownerHome':role()==='seller'?'#sellerHome':null;
 return `<div class="store-shell">
 <div class="store-utility"><span>${ico("sparkle")} Belanja nyaman bersama Klikchart</span><span>Kontak dukungan: ${E(S.site?.support_email||'pusat bantuan Klikchart')}</span></div>
 <header class="store-header"><div class="store-header-inner"><a class="store-brand" href="#home" aria-label="Klikchart beranda"><span class="store-bag">${logo}</span><strong>${E(S.site?.storefront_name||'klikchart')}</strong><small>SHOP</small></a>
 <label class="store-search"><span aria-hidden="true">${ico("search")}</span><input id="global-q" aria-label="Cari produk" autocomplete="off" placeholder="Cari produk, kategori, dan kebutuhanmu..." value="${E(S.q)}"><span class="search-enter">ENTER ↵</span></label>
 <nav class="store-actions" aria-label="Navigasi toko"><a href="${cartLink}" aria-label="Keranjang">${ico("cart")} <span class="desktop-label">Keranjang</span></a>${isLogged()?profilePopup():`<a href="/login" aria-label="Masuk ke akun">${ico('account')} <span class="desktop-label">Masuk</span></a>`}${roleLink?`<a class="console-link" href="${roleLink}">Panel ${role()==='owner'?'Owner':'Penjual'} ↗</a>`:''}</nav></div></header>
 <nav class="store-nav"><div class="store-nav-inner"><a href="#home" class="${S.view==='home'?'on':''}">Beranda</a><a href="#home" data-action="reset-filters">Semua produk</a>${isLogged()?`<a href="#wishlist">Favorit</a><a href="#orders">Pesanan saya</a><a href="#addresses">Alamat</a><a href="#account">Akun & pengaturan</a>${role()==='buyer'?'<a href="#apply">Buka toko</a>':''}`:`<a href="/register">Daftar gratis</a>`}<span class="store-safe">${ico("sparkle")} Klikchart Commerce</span></div></nav>
 <main class="store-main">${inner}</main><footer class="store-footer"><div><strong>${E(S.site?.storefront_name||'klikchart')}</strong><p>Marketplace pilihan untuk kebutuhanmu.</p></div><div><b>Pusat Bantuan</b><p>${E(S.site?.support_email||'Hubungi pengelola marketplace')}</p></div><div><b>Transaksi</b><p>COD internal · Pengiriman manual · Belum ada payment gateway.</p></div><small>© 2026 Klikchart Commerce</small></footer>
 <nav class="store-bottom" aria-label="Navigasi cepat"><a href="#home">${ico('home')}<small>Belanja</small></a><a href="${cartLink}">${ico('cart')}<small>Keranjang</small></a><a href="${isLogged()?'#orders':'/login'}">${ico('orders')}<small>Pesanan</small></a><a href="${quickLink}">${ico('account')}<small>Akun</small></a></nav></div>`;
}
function layout(inner){const gr=groups();return `<div class="sidebar-backdrop" id="backdrop"></div><div class="layout"><aside class="sidebar" id="sidebar"><a href="#${start()}" class="brand"><span class="brand-icon">${logo}</span><span>${E(S.site?.storefront_name||'klikchart')}<small>COMMERCE CENTER</small></span></a>
 <div class="nav-caption">${role()==='owner'?'WORKSPACE OWNER':'WORKSPACE PENJUAL'}</div>
 ${gr.map((items,i)=>`<div class="nav-group">${i>0?'<div class="nav-caption">MANAJEMEN</div>':''}${items.map(([key,label])=>`<a class="nav-link ${S.view===key?'active':''}" href="#${key}" ${S.view===key?'aria-current="page"':''}><span class="nav-ico">${ico(key)}</span>${E(label)}</a>`).join('')}</div>`).join('')}
 <div class="sidebar-bottom"><div class="nav-caption">LAINNYA</div><a class="nav-link" href="#home"><span class="nav-ico">${ico('home')}</span>Lihat etalase <span class="nav-arrow">↗</span></a><a class="nav-link ${S.view==='account'?'active':''}" href="#account"><span class="nav-ico">${ico('account')}</span>Akun & pengaturan</a><button data-action="logout" class="nav-link"><span class="nav-ico">${ico("logout")}</span>Keluar</button><a href="#account" class="user-badge" aria-label="Lihat profil saya">${avatarMarkup()}<span>${E(displayWho())}<small>${E(roleLabel())}</small></span></a></div></aside>
 <main class="main"><header class="topbar"><button class="mobile-menu" id="menu" aria-label="Buka menu" type="button">${ico("menu")}</button><div class="top-context"><span class="top-context-mark">${ico(S.view)}</span><div><small>${role()==='owner'?'OWNER CENTER':'SELLER CENTER'}</small><strong>${E(names[S.view]||'Dashboard')}</strong></div></div><div class="top-actions"><a class="top-store-link" href="#home">${ico('home')} <span>Lihat toko</span> ↗</a>${profilePopup()}</div></header><div class="content">${inner}<div class="footer">© 2026 Klikchart Commerce · Belanja, toko, dan pengaturan dalam satu tempat</div></div></main></div>`}
const heading=(title,sub,tools='')=>`<div class="intro"><div><p class="eyebrow">KLIKCHART / ${role().toUpperCase()}</p><h1>${title}</h1><p>${E(sub)}</p></div>${tools?`<div class="tools">${tools}</div>`:''}</div>`;
const productCard=p=>`<article class="product-card store-product-card"><button type="button" class="product-cover store-product-photo" data-action="view-product:${p.id}" aria-label="Lihat detail ${E(p.name)}">${pic(p)}${Number(p.stock)===0?'<span class="soldout">Stok habis</span>':''}</button><div class="product-info"><small class="shop-label">${ico("sellerShop")} ${E(p.market_shops?.name||'Klikchart Store')}</small><h3>${E(p.name)}</h3><div class="price">${money(p.price)}</div><div class="product-meta"><span>Stok ${Number(p.stock)}</span><span>${ico("sparkle")} Toko terverifikasi</span></div><div class="product-buttons">${btn('Detail','view-product:'+p.id,'small')}${isLogged()?btn('Tambah ke keranjang','cart-add:'+p.id,'primary small'):`<a class="btn primary small" href="/login">Masuk</a>`}</div></div></article>`;
const orderTable=(orders,mode)=>orders?.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Pesanan</th><th>Toko / pembeli</th><th>Total</th><th>COD</th><th>Status</th><th>Tindakan</th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong>#${E(o.id.slice(0,8).toUpperCase())}</strong><div class="small-muted">${fmt(o.created_at)}</div>${(o.market_order_items||[]).map(i=>`<div class="small-muted">${E(i.product_name)} × ${i.quantity}</div>`).join('')}</td><td>${E(o.market_shops?.name||'Toko')}<div class="small-muted">${mode==='owner'?E(o.buyer_id.slice(0,8)):'COD'}</div></td><td><strong>${money(o.total)}</strong></td><td>${o.payment_status==='seller_reported_collected'?badge('delivered'):E('Bayar saat terima')}</td><td>${badge(o.status)}${o.tracking_note?`<div class="small-muted">Resi: ${E(o.tracking_note)}</div>`:''}</td><td><div class="pill-row">${orderButtons(o,mode)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pesanan','Pesanan baru akan tampil di sini.');
function orderButtons(o,mode){const transitions=mode==='buyer'?{pending:[['canceled','Batalkan']],shipped:[['delivered','Sudah diterima']]}:mode==='seller'||mode==='owner'?{pending:[['accepted','Terima'],['canceled','Tolak']],accepted:[['packed','Sudah dikemas'],['canceled','Batalkan']],packed:[['shipped','Kirim barang']]}:{};
 const primary=(transitions[o.status]||[]).map(([val,label])=>btn(E(label),'order:'+o.id+':'+val,'small')).join('');const extras=mode==='buyer'&&o.status==='delivered'?(o.market_order_items||[]).map(i=>btn('★ Ulasan','review:'+i.product_id,'small')).join(''):mode!=='buyer'&&o.status==='delivered'&&o.payment_status==='pay_on_delivery'?btn('Catat COD diterima','cod:'+o.id,'small'):'';return primary+extras||'<span class="small-muted">—</span>'}
function flash(html){
 document.documentElement.dataset.theme=S.theme==='system'?(window.matchMedia?.('(prefers-color-scheme:dark)').matches?'dark':'light'):S.theme;
 const app=document.getElementById('app');
 if(isStore()){
  // Storefront has different navigation, layout and responsive breakpoints than admin consoles.
  if(!app.querySelector('.store-shell')){app.innerHTML=storeLayout(html);wire();return}
  const content=app.querySelector('.store-main');if(content)content.innerHTML=html;
  app.querySelectorAll('.store-nav-inner a[href^="#"]').forEach(n=>n.classList.toggle('on',n.getAttribute('href')==='#'+S.view));
  wireContent();return;
 }
 if(!app.querySelector('.layout')){app.innerHTML=layout(html);wire();return}
 const content=app.querySelector('.content');if(content)content.innerHTML=html+'<div class="footer">© 2026 Klikchart Commerce · COD internal · Pengiriman manual</div>';
 app.querySelectorAll('.nav-link[href^="#"]').forEach(n=>n.classList.toggle('active',n.getAttribute('href')==='#'+S.view));
 const ctx=app.querySelector('.top-context strong');if(ctx)ctx.textContent=names[S.view]||'Dashboard';
 const ctxIcon=app.querySelector('.top-context-mark');if(ctxIcon)ctxIcon.innerHTML=ico(S.view);
 // Account menu is preserved when switching owner/seller pages; label is refreshed after a profile edit.
 const brand=app.querySelector('.sidebar .brand span:last-child');if(brand?.firstChild)brand.firstChild.nodeValue=S.site?.storefront_name||'klikchart';
 const badgeName=app.querySelector('.user-badge > span:last-child');if(badgeName?.firstChild)badgeName.firstChild.nodeValue=displayWho();
 wireContent();
}
function refreshAccountChrome(){
 document.querySelectorAll('.profile-menu-host').forEach(host=>{const temporary=document.createElement('div');temporary.innerHTML=profilePopup();host.replaceWith(temporary.firstElementChild)});
 const badge=document.querySelector('.user-badge');if(badge){const a=badge.querySelector('.avatar');if(a){const holder=document.createElement('div');holder.innerHTML=avatarMarkup();a.replaceWith(holder.firstElementChild)}const name=badge.querySelector(':scope > span:last-child');if(name){name.firstChild.textContent=displayWho();const small=name.querySelector('small');if(small)small.textContent=roleLabel()}}
}
function wireContent(){document.getElementById('cat-filter')?.addEventListener('change',e=>{S.category=e.target.value;S.page=1;load()});document.getElementById('sort-filter')?.addEventListener('change',e=>{S.sort=e.target.value;S.page=1;load()});}

let dialogReturnFocus=null;
function closeDialog(){document.getElementById('modal')?.dispatchEvent(new Event('kc-dialog-close'));document.getElementById('modal')?.remove();document.body.classList.remove('dialog-open');if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus({preventScroll:true});dialogReturnFocus=null;}
function dialog(title,body,footer=''){
 closeDialog();dialogReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
 const x=document.createElement('div');x.id='modal';x.className='overlay';
 x.innerHTML=`<div class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><div class="dialog-head"><h2 id="dialog-title">${E(title)}</h2><button type="button" class="dialog-close" data-action="dialog-close" aria-label="Tutup dialog">✕</button></div>${body}${footer?`<div class="dialog-footer">${footer}</div>`:''}</div>`;
 document.body.appendChild(x);document.body.classList.add('dialog-open');
 x.addEventListener('click',event=>{if(event.target===x)closeDialog()});
 x.querySelector('input:not([type=hidden]),select,textarea,button')?.focus({preventScroll:true});
}
async function confirmAction(title,description,{confirmLabel='Konfirmasi',fieldLabel='',fieldValue='',required=false,danger=false}={}){
  dialog(title,`<p class="confirm-description">${E(description)}</p>${fieldLabel?`<div class="field"><label for="kc-confirm-note">${E(fieldLabel)}</label><textarea id="kc-confirm-note" rows="3" maxlength="300" ${required?'required':''}>${E(fieldValue)}</textarea></div>`:''}<div class="dialog-footer"><button class="btn" type="button" data-action="dialog-close">Kembali</button><button class="btn ${danger?'danger':'primary'}" type="button" id="kc-confirm-accept">${E(confirmLabel)}</button></div>`);
  const modal=document.getElementById('modal');
  return new Promise(resolve=>{
    let completed=false;
    const settle=value=>{if(completed)return;completed=true;resolve(value)};
    modal.addEventListener('kc-dialog-close',()=>settle(null),{once:true});
    modal.querySelector('#kc-confirm-accept')?.addEventListener('click',()=>{
      const field=modal.querySelector('#kc-confirm-note');
      if(field && required && !field.value.trim()){field.setCustomValidity('Kolom ini wajib diisi.');field.reportValidity();field.addEventListener('input',()=>field.setCustomValidity(''),{once:true});return}
      const value={note:field?.value.trim()||''};
      settle(value);closeDialog();
    });
    modal.querySelector('#kc-confirm-accept')?.focus({preventScroll:true});
  });
}
function formFields(parts){return `<div class="form-grid">${parts.map(([key,label,type,value,wide,extra])=>{const optional=['description','imageUrl','comment'].includes(key);return `<div class="field ${wide?'wide':''}"><label for="f-${E(key)}">${E(label)}</label>${type==='textarea'?`<textarea id="f-${E(key)}" name="${E(key)}" maxlength="3000" ${optional?'':'required'}>${E(value)}</textarea>`:type==='select'?`<select id="f-${E(key)}" name="${E(key)}">${extra.map(([v,t])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(t)}</option>`).join('')}</select>`:`<input id="f-${E(key)}" name="${E(key)}" type="${type}" value="${E(value)}" ${type==='number'?'min="0" step="1"':''} ${optional?'':'required'}>`}</div>`}).join('')}</div>`}
function formDialog(title,formKind,fields,submitLabel='Simpan'){dialog(title,`<form id="dialog-form" data-form="${formKind}">${formFields(fields)}<div class="dialog-footer"><button class="btn" type="button" data-action="dialog-close">Batal</button><button class="btn primary" type="submit">${E(submitLabel)}</button></div></form>`)}
async function load(){const ticket=++S.epoch;const v=S.view;const p={};try{
 if(v==='home'||v==='shop'){const params=new URLSearchParams({page:String(S.page),sort:S.sort});if(S.q)params.set('q',S.q);if(S.category)params.set('category',S.category);if(S.minPrice)params.set('minPrice',S.minPrice);if(S.maxPrice)params.set('maxPrice',S.maxPrice);if(v==='shop'&&S.shopId)params.set('shop',S.shopId);p.products=await api('products?'+params);if(v==='shop'&&S.shopId)p.shop=await api('shops/'+S.shopId)}
 if(v==='product'&&S.productId)p.detail=await api('products/'+S.productId);
 if(v==='account'){p.profile=await api('profile');S.profileSnapshot=p.profile;}if(v==='ownerUsers')p.users=await api('owner/users?page='+S.userPage);if(v==='ownerSettings')p.site=await api('site-settings');if(v==='ownerShops')p.shops=await api('owner/shops?page='+S.shopPage);
 if(v==='cart')p.cart=await api('cart');if(v==='wishlist')p.wishlist=await api('wishlist');if(v==='addresses')p.addresses=await api('addresses');if(v==='orders')p.orders=await api('orders?page='+S.orderPage);
 if(v==='sellerHome')p.stats=await api('seller/stats');if(v==='sellerProducts')p.sellerProducts=await api('seller/products?page='+S.sellerPage);if(v==='sellerOrders')p.orders=await api('orders?scope=selling&page='+S.orderPage);if(v==='sellerShop')p.shop=S.me?.shop;
 if(v==='ownerHome')p.stats=await api('owner/stats');if(v==='ownerApplications')p.applications=await api('owner/applications');if(v==='ownerProducts')p.ownerProducts=await api('owner/products?page='+S.ownerProductPage);if(v==='ownerOrders')p.orders=await api('orders?scope=all&page='+S.orderPage);
 if(ticket!==S.epoch)return;S.data=p;if(p.profile)refreshAccountChrome();if(p.profile?.settings?.theme)S.theme=p.profile.settings.theme;render();
 }catch(e){if(ticket!==S.epoch)return;if(e.code==='UNAUTHORIZED'){S.me=null;S.view='home';location.hash='#home';return}flash(heading('Ada kendala','Periksa pesan kesalahan berikut.')+`<div class="notice error">${E(msg(e))}</div>${btn('Coba lagi','reload','primary')}`)}}
function storefrontToolbar(){return `<section class="store-categories" aria-label="Kategori populer"><button class="category-chip ${!S.category?'selected':''}" data-action="category:">${ico("sparkle")} Semua kategori</button>${S.categories.map(c=>`<button class="category-chip ${String(S.category)===String(c.id)?'selected':''}" data-action="category:${c.id}">${E(c.name)}</button>`).join('')}</section>`;}
function storeProducts(){const {items=[],total=0,page=1}=S.data.products||{};return `<div class="store-list-heading"><div><span class="eyebrow">JELAJAHI KATALOG</span><h2>${S.view==='shop'?'Katalog toko':'Rekomendasi untukmu'}</h2><p>${total} produk ditemukan</p></div></div>
 <div class="catalog-toolbar"><select class="control" id="cat-filter" aria-label="Kategori"><option value="">Semua kategori</option>${S.categories.map(c=>`<option value="${c.id}" ${String(S.category)===String(c.id)?'selected':''}>${E(c.name)}</option>`).join('')}</select><input class="control price-limit" inputmode="numeric" type="number" min="0" id="min-price" placeholder="Harga minimum" aria-label="Harga minimum" value="${E(S.minPrice)}"><input class="control price-limit" inputmode="numeric" type="number" min="0" id="max-price" placeholder="Harga maksimum" aria-label="Harga maksimum" value="${E(S.maxPrice)}"><select id="sort-filter" class="control" aria-label="Urutan"><option value="new" ${S.sort==='new'?'selected':''}>Terbaru</option><option value="price_asc" ${S.sort==='price_asc'?'selected':''}>Harga terendah</option><option value="price_desc" ${S.sort==='price_desc'?'selected':''}>Harga tertinggi</option><option value="name" ${S.sort==='name'?'selected':''}>Nama A–Z</option></select>${btn('Terapkan harga','apply-price','small')}</div>
 ${items.length?`<div class="product-grid storefront-grid">${items.map(productCard).join('')}</div><div class="tools store-pagination">${page>1?btn('← Sebelumnya','prev'):''}<span class="hint">Halaman ${page} dari ${Math.max(1,Math.ceil(total/16))}</span>${page*16<total?btn('Berikutnya →','next'):''}</div>`:empty('Belum ada produk yang sesuai','Ubah filter atau jelajahi kategori lainnya.')}`;}
function home(){return `<section class="store-hero"><div class="store-hero-copy"><span class="hero-kicker">${ico("sparkle")} TEMUKAN PILIHAN TERBAIKMU</span><h1>Belanja lebih mudah.<br><em>Pilihan lebih beragam.</em></h1><p>${E(S.site?.announcement||'Temukan produk dari berbagai toko dan selesaikan belanja dengan mudah.')}</p><div class="hero-cta">${btn('Jelajahi produk','scroll-products','primary')}${isLogged()?btn('Lihat pesanan','go:orders','soft'):`<a class="btn soft" href="/register">Daftar sekarang</a>`}</div><span class="hero-trust">${ico("shield")} Toko terverifikasi &nbsp; · &nbsp; ${ico("package")} COD internal</span></div><div class="hero-decor" aria-hidden="true"><div class="orb-one"></div><div class="orb-two"></div><div class="hero-bag">${logo}</div><span class="hero-tag">${ico("sparkle")} BELANJA</span><span class="hero-spark">${ico("sparkle")}</span></div></section>
 <section class="store-benefits"><span>${ico("sparkle")} <b>Marketplace terkurasi</b><small>Penjual ditinjau pengelola</small></span><span>${ico("wishlist")} <b>Simpan favorit</b><small>Temukan kembali pilihanmu</small></span><span>${ico("package")} <b>Riwayat pesanan</b><small>Pantau proses pengiriman</small></span></section>
 ${storefrontToolbar()}<div id="products-section">${storeProducts()}</div>`;}
function shop(){const x=S.data.shop?.shop;if(!x)return empty('Toko tidak ditemukan');return `<div class="shop-page-head"><span class="shop-avatar">${ico("sellerShop")}</span><div><span class="eyebrow">TOKO TERVERIFIKASI</span><h1>${E(x.name)}</h1><p>${E(x.description||'Toko mitra Klikchart.')} · Bergabung ${fmt(x.created_at)}</p></div>${btn('Semua toko','go:home','soft')}</div>${storeProducts()}`;}
function productDetail(){const x=S.data.detail?.product;if(!x)return empty('Produk tidak tersedia');const images=(Array.isArray(x.images)?x.images:[]).filter(Boolean);if(!images.length&&x.image_url)images.push(x.image_url);const selected=images[S.activePhoto]||images[0]||null;
 return `<div class="breadcrumbs"><a href="#home">Beranda</a><span>›</span><span>${E(x.market_categories?.name||'Produk')}</span><span>›</span><b>${E(x.name)}</b></div><div class="store-product-detail"><div class="gallery"><div class="gallery-main">${selected?`<img src="${E(selected)}" alt="Foto ${E(x.name)}" loading="eager">`:'<span class="gallery-placeholder">'+ico('package')+'</span>'}</div>${images.length>1?`<div class="gallery-thumbs">${images.map((img,i)=>`<button class="${S.activePhoto===i?'on':''}" data-action="gallery:${i}" aria-label="Tampilkan foto ${i+1}"><img src="${E(img)}" alt="Foto produk ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}</div>
 <div class="detail-summary"><span class="eyebrow">PRODUK PILIHAN KLIKCHART</span><h1>${E(x.name)}</h1><span class="detail-rating">★ ${Number(S.data.detail?.rating?.average||0).toFixed(1)} <small>(${Number(S.data.detail?.rating?.count||0)} ulasan)</small></span><div class="detail-price">${money(x.price)}</div><p class="detail-stock">${Number(x.stock)>0?'✓ Stok tersedia: '+Number(x.stock):'Stok sedang habis'}</p><p class="detail-desc">${E(x.description||'Penjual belum menambahkan deskripsi produk.')}</p><div class="detail-actions">${Number(x.stock)>0?(isLogged()?btn('Masukkan keranjang','cart-add:'+x.id,'primary'): `<a class="btn primary" href="/login">Masuk untuk membeli</a>`):'<span class="notice warn">Stok produk sedang kosong</span>'}${isLogged()?btn('Simpan favorit','wishlist-add:'+x.id,'soft'):''}</div><div class="seller-card"><span>${ico("sellerShop")}</span><div><small>Dijual oleh</small><b>${E(x.market_shops?.name||'Toko Klikchart')}</b><p>Penjual telah melalui proses persetujuan.</p></div>${btn('Kunjungi toko','visit-shop:'+x.shop_id,'small')}</div><div class="detail-disclaimer">Pembayaran tersedia: COD internal. Informasi ongkir final terlihat di keranjang sebelum checkout.</div></div></div>
 ${panel('Ulasan dari pembelian selesai',(S.data.detail?.reviews||[]).length?S.data.detail.reviews.map(r=>`<div class="flow"><div><div class="star">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><div class="hint">${E(r.comment||'Tanpa komentar.')} · ${fmt(r.created_at)}</div></div></div>`).join(''):empty('Belum ada ulasan'))}`;}

function cart(){const items=(S.data.cart?.items||[]).filter(c=>c.market_products),usable=items.filter(c=>c.market_products.status==='published'&&c.market_products.market_shops?.status==='active');const subtotal=usable.reduce((s,c)=>s+c.quantity*Number(c.market_products.price),0);const shopCount=new Set(usable.map(c=>c.market_products.shop_id)).size;return heading('Keranjang Belanja','Jumlah stok dan harga diverifikasi kembali di database saat checkout.',btn('Cari produk','go:home'))+`<div class="split">${panel('Produk dalam keranjang',items.length?items.map(i=>`<div class="flow"><div class="flow-main"><span class="mini-art">${pic(i.market_products)}</span><div><strong>${E(i.market_products.name)}</strong><small>${money(i.market_products.price)} × ${i.quantity} · Stok ${i.market_products.stock}</small></div></div><div class="flow-actions">${btn('−','cart-qty:'+i.product_id+':'+(i.quantity-1),'small')}${i.quantity}${btn('+','cart-qty:'+i.product_id+':'+(i.quantity+1),'small')}${btn('Hapus','cart-qty:'+i.product_id+':0','danger small')}</div></div>`).join(''):empty('Keranjang kosong','Tambahkan produk dari katalog.'))}${panel('Ringkasan belanja',`<div class="summary-line"><span>Subtotal produk</span><b>${money(subtotal)}</b></div><div class="summary-line"><span>Ongkir perkiraan (${shopCount} toko)</span><b>${money(shopCount*Number(S.site?.shipping_fee??15000))}</b></div><div class="summary-line line"><strong>Total pembayaran COD</strong><b>${money(subtotal+shopCount*Number(S.site?.shipping_fee??15000))}</b></div><p class="hint">Ongkir sesuai tarif yang ditetapkan pengelola marketplace; pembayaran masih COD. Tidak terintegrasi dengan kurir atau payment gateway.</p>${usable.length?btn('Lanjut ke checkout','checkout','primary full'):'<button type="button" class="btn primary full" disabled>Keranjang belum siap checkout</button>'}`)}</div>`}
function addresses(){const items=S.data.addresses?.items||[];return heading('Alamat Pengiriman','Simpan alamat untuk transaksi COD.',btn('Tambah alamat','address-new','primary'))+panel('Alamat yang tersimpan',items.length?items.map(a=>`<div class="flow"><div><strong>${E(a.recipient)}</strong> · ${E(a.phone)}<div class="hint">${E(a.address)}, ${E(a.city)}, ${E(a.province)} ${E(a.postal_code)}</div></div><div class="pill-row">${btn('Edit','address-edit:'+a.id,'small')}${btn('Hapus','address-delete:'+a.id,'danger small')}</div></div>`).join(''):empty('Belum ada alamat','Tambahkan alamat lengkap sebelum checkout.'))}
function wishlist(){const items=S.data.wishlist?.items||[];return heading('Produk Favorit','Simpan produk yang ingin kamu beli nanti.',btn('Jelajahi katalog','go:home'))+`<div class="product-grid">${items.map(i=>i.market_products?`<div>${productCard({...i.market_products,market_shops:{name:'Klikchart Store'}})}<div style="padding:5px 0">${btn('Hapus favorit','wishlist-remove:'+i.product_id,'danger small')}</div></div>`:'').join('')}</div>${!items.length?empty('Belum ada favorit'):''}`}
function orders(mode='buyer'){return heading(mode==='buyer'?'Pesanan Saya':mode==='seller'?'Pesanan Masuk':'Seluruh Pesanan','Pantau alur pesanan dari konfirmasi sampai barang diterima.')+panel('Riwayat pesanan',orderTable(S.data.orders?.items,mode)+`<div class="tools store-pagination">${S.orderPage>1?btn('← Sebelumnya','orders-prev','small'):''}<span class="hint">Halaman ${S.orderPage} · ${Number(S.data.orders?.total||0)} pesanan</span>${S.orderPage*25<Number(S.data.orders?.total||0)?btn('Berikutnya →','orders-next','small'):''}</div>`);}
function apply(){const a=S.me?.application;return heading('Daftar Jadi Penjual','Buka toko setelah kontak Email dan WhatsApp terverifikasi serta disetujui owner.')+(!S.me?.user?.emailVerified||!S.me?.user?.whatsappVerified?`<div class="notice warn">Aktifkan kedua kontak dari <a class="link" href="#account" data-action="account-contact">Akun & Pengaturan</a> sebelum mengajukan toko.</div>`:'')+panel('Status pengajuan',a?`<div class="flow"><div><strong>${E(a.store_name)}</strong><div class="hint">${E(a.owner_note||'Menunggu pemeriksaan oleh owner.')}</div></div>${badge(a.status)}</div>`:empty('Belum pernah mengajukan toko'))+(!a||a.status==='rejected'?panel('Ajukan toko baru',`<form data-form="seller-apply">${formFields([['storeName','Nama toko','text','',true],['description','Deskripsi toko','textarea','',true]])}<div style="margin-top:16px"><button class="btn primary" type="submit">Ajukan verifikasi toko</button></div></form>`):'')}
function sellerHome(){const d=S.data.stats||{};return heading('Selamat datang, '+E(who())+'!','Ringkasan performa toko berdasarkan transaksi aktual.',btn('+ Tambah produk','product-new','primary'))+`<div class="kpis">${metric('Produk toko',d.productCount||0,ico('package'))}${metric('Pesanan masuk',d.orderCount||0,ico('package'))}${metric('Nilai pesanan aktif',money(d.orderTotal),ico('orders'),'Berdasarkan total pesanan aktif')}${metric('Stok rendah',d.lowStock||0,'!','Produk dengan stok ≤ 5')}</div><div class="notice">Penjual mengelola katalog, stok, dan pengiriman. Metode checkout saat ini hanya COD, tanpa pembayaran digital otomatis.</div>${panel('Pesanan terkini',(d.recent||[]).length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Pesanan</th><th>Nilai</th><th>Status</th><th>Tanggal</th></tr></thead><tbody>${d.recent.map(o=>`<tr><td>#${E(o.id.slice(0,8))}</td><td>${money(o.total)}</td><td>${badge(o.status)}</td><td>${fmt(o.created_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada pesanan'),btn('Kelola pesanan','go:sellerOrders','small'))}`}
function sellerProducts(){const info=S.data.sellerProducts||{};const data=info.items||[];return heading('Kelola Produk','Tambahkan produk, edit harga, stok, dan status penayangan.',btn('+ Produk baru','product-new','primary'))+panel('Katalog toko',data.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Produk</th><th>Harga</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.map(p=>`<tr><td><div class="flow-main"><span class="mini-art">${pic(p)}</span><strong>${E(p.name)}</strong></div></td><td>${money(p.price)}</td><td>${p.stock}</td><td>${badge(p.status)}</td><td>${btn('Edit','product-edit:'+p.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada produk','Klik Produk baru untuk mulai berjualan.'))+productPager(info,'seller-products')}
function sellerShop(){const s=S.me.shop;return heading('Pengaturan Toko','Identitas dan informasi publik toko penjual.')+panel('Profil toko',`<form data-form="shop-edit">${formFields([['name','Nama toko','text',s?.name||'',true],['description','Deskripsi toko','textarea',s?.description||'',true]])}<div style="margin-top:17px"><button type="submit" class="btn primary">Simpan toko</button></div></form>`)}
function ownerHome(){const d=S.data.stats||{};return heading('Owner Control Center','Pengelolaan terpusat toko, produk, pengajuan, dan pesanan.',btn('Review penjual','go:ownerApplications','primary'))+`<div class="kpis">${metric('Akun terverifikasi',d.users||0,ico('account'))}${metric('Jumlah toko',d.sellers||0,ico('sellerShop'))}${metric('Pesanan',d.orders||0,ico('package'))}${metric('Produk terdaftar',d.products||0,ico('package'))}</div><div class="grid2">${panel('Nilai pesanan',`<div class="kpi-value">${money(d.grossOrders||0)}</div><p class="hint">Total nilai order tidak dibatalkan, bukan laba platform atau pembayaran yang sudah diterima.</p><div class="stat-chart" role="img" aria-label="Nilai pesanan per bulan">${(d.trend||[]).map(v=>`<div title="${E(v.label)}: ${money(v.value)}" style="height:${Math.max(3,Math.round(100*v.value/Math.max(1,...(d.trend||[]).map(x=>x.value))))}%"></div>`).join('')}</div><div class="small-muted">Nilai pesanan enam bulan terakhir dari database · tidak termasuk pesanan dibatalkan</div>`)}${panel('Antrian moderasi',`<div class="kpi-value">${d.pendingApplications||0}</div><p class="hint">Pengajuan penjual yang menunggu pemeriksaan</p>${btn('Buka antrian','go:ownerApplications','primary')}`)}</div>${panel('Toko terdaftar',(d.shops||[]).length?d.shops.slice(0,7).map(s=>`<div class="flow"><div><strong>${E(s.name)}</strong></div>${badge(s.status)}</div>`).join(''):empty('Belum ada toko'))}`}
function ownerApps(){const data=S.data.applications?.items||[];return heading('Verifikasi Penjual','Cek identitas akun, nama toko, dan informasi sebelum memberi akses penjual.')+panel('Pengajuan',data.length?data.map(a=>`<div class="flow"><div class="flow-main"><span class="mini-art">${ico("sellerShop")}</span><div><strong>${E(a.store_name)}</strong><small>${fmt(a.created_at)} · ${E(a.user_id.slice(0,8))}</small><p class="hint">${E(a.description)}</p><small>${E(a.owner_note)}</small></div></div><div class="flow-actions">${badge(a.status)}${a.status==='pending'?btn('Setujui','application:'+a.user_id+':approved','primary small')+btn('Tolak','application:'+a.user_id+':rejected','danger small'):''}</div></div>`).join(''):empty('Tidak ada pengajuan'))}
function ownerShops(){const d=S.data.shops||{};return heading('Kelola Seluruh Toko','Aktifkan atau tangguhkan toko dengan akses owner.')+panel('Toko',(d.items||[]).length?d.items.map(s=>`<div class="flow"><div><strong>${E(s.name)}</strong><div class="small-muted">ID ${E(s.id.slice(0,8))} · Owner ${E(s.owner_id.slice(0,8))}</div></div><div class="flow-actions">${badge(s.status)}${btn(s.status==='active'?'Tangguhkan':'Aktifkan','shop-status:'+s.id+':'+(s.status==='active'?'suspended':'active'),s.status==='active'?'danger small':'primary small')}</div></div>`).join('')+`<div class="tools" style="margin-top:16px">${btn('← Sebelumnya','shops-prev','small')}<span class="hint">Halaman ${d.page||1} · ${d.total||0} toko</span>${btn('Berikutnya →','shops-next','small')}</div>`:empty('Belum ada toko'))}
function ownerProducts(){const info=S.data.ownerProducts||{};const data=info.items||[];return heading('Moderasi Produk','Owner dapat mengarsipkan produk yang melanggar aturan.')+panel('Semua produk',data.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Nama</th><th>Toko</th><th>Harga</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.map(p=>`<tr><td>${E(p.name)}</td><td>${E(p.market_shops?.name||'')}</td><td>${money(p.price)}</td><td>${badge(p.status)}</td><td>${btn(p.status==='published'?'Arsipkan':'Tayangkan','mod-product:'+p.id+':'+(p.status==='published'?'archived':'published'),'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada produk'))+productPager(info,'owner-products')}
function categoryAdmin(){return heading('Kategori Produk','Kategori digunakan untuk mengelompokkan produk di katalog.',btn('+ Tambah kategori','category-new','primary'))+panel('Kategori tersedia',(S.categories||[]).map(c=>`<div class="flow"><strong>${E(c.name)}</strong><span class="hint">${E(c.slug)}</span></div>`).join(''))}
function account(){
 const a=S.data.profile?.account||{},u=S.data.profile?.settings||{};
 const tabs=[['info','Profil saya'],['security','Keamanan'],['preferences','Preferensi'],['activity','Aktivitas']];
 const tabsHtml=`<div class="account-tabs" role="tablist" aria-label="Pengaturan akun">${tabs.map(([key,label])=>`<button type="button" class="account-tab ${S.accountTab===key?'selected':''}" id="account-tab-${key}" data-action="account-tab:${key}" role="tab" aria-controls="account-panel" aria-selected="${S.accountTab===key}" tabindex="${S.accountTab===key?0:-1}">${label}</button>`).join('')}</div>`;
 const info=panel('Informasi profil',`<p class="hint">Kelola identitas yang terlihat di Klikchart. Email dan WhatsApp dilindungi oleh verifikasi OTP, sehingga tidak bisa diganti dari formulir ini.</p><form data-form="profile-update" class="profile-edit-form"><div class="profile-edit-header"><span id="profile-avatar-preview">${avatarMarkup('account-avatar edit-avatar')}</span><span><strong>Foto profil</strong><small>Gunakan tautan gambar HTTPS yang dapat diakses publik. Pratinjau akan diperbarui sebelum disimpan.</small></span></div><div class="form-grid"><div class="field"><label for="pf-username">Nama pengguna</label><input id="pf-username" name="username" minlength="3" maxlength="20" pattern="[A-Za-z0-9._]{3,20}" autocomplete="username" required value="${E(a.username||'')}"><small class="form-note">3–20 karakter; huruf, angka, titik, garis bawah.</small></div><div class="field"><label for="pf-displayName">Nama tampilan</label><input id="pf-displayName" name="displayName" maxlength="80" autocomplete="nickname" value="${E(u.display_name||'')}"></div><div class="field wide"><label for="pf-bio">Tentang saya</label><textarea id="pf-bio" name="bio" maxlength="500" rows="3" placeholder="Ceritakan sedikit tentang akunmu...">${E(u.bio||'')}</textarea><small class="form-note">Maksimal 500 karakter.</small></div><div class="field wide"><label for="pf-avatarUrl">URL foto profil (opsional)</label><input id="pf-avatarUrl" name="avatarUrl" type="url" inputmode="url" maxlength="500" placeholder="https://contoh.com/foto.jpg" value="${E(u.avatar_url||'')}"><small class="form-note" id="avatar-help">Hanya tautan HTTPS; tidak menyimpan foto langsung di Klikchart.</small></div></div><div class="profile-form-actions"><button type="submit" class="btn primary">${ico('account')} Simpan perubahan profil</button><span class="hint">Perubahan tersimpan di Supabase.</span></div></form>`);
 const contact=(channel,label,value,verified)=>`<div class="flow profile-contact"><div class="flow-main"><span class="contact-symbol">${ico(channel==='email'?'email':'phone')}</span><div><strong>${label}</strong><small>${E(value||'Belum tersedia')}</small></div></div><div class="flow-actions">${verified?'<span class="status green">Terverifikasi</span>':`<span class="status orange">Belum terverifikasi</span>${btn('Verifikasi','contact-send:'+channel,'small')}`}</div></div>`;
 const secret=(id,name,label,autocomplete)=>`<div class="field"><label for="${id}">${label}</label><div class="password-field"><input id="${id}" type="password" name="${name}" autocomplete="${autocomplete}" ${id==='sec-current'?'':'minlength="8" maxlength="72"'} required><button type="button" class="password-eye" data-action="password-visibility:${id}" aria-label="Tampilkan ${label.toLowerCase()}" aria-pressed="false">${ico('eye')} <span>Tampilkan</span></button></div></div>`;
 const security=panel('Kata sandi & sesi masuk',`<p class="hint">Untuk mengubah sandi, masukkan sandi saat ini. Setelah tersimpan, semua sesi sebelumnya tidak berlaku dan kamu harus login kembali.</p><form data-form="password-change" class="password-form">${secret('sec-current','currentPassword','Kata sandi saat ini','current-password')}${secret('sec-new','newPassword','Kata sandi baru','new-password')}${secret('sec-confirm','confirmPassword','Ulangi kata sandi baru','new-password')}<p class="hint">Gunakan minimal 8 karakter dengan huruf dan angka. Jangan bagikan kata sandi atau kode OTP kepada siapa pun.</p><button type="submit" class="btn primary">Perbarui kata sandi</button></form>`)+panel('Metode verifikasi kontak',`<p class="hint">Email dan WhatsApp diverifikasi masing-masing melalui kode OTP. Kontak yang belum diverifikasi tetap bisa dilengkapi tanpa membuat akun baru.</p>${contact('email','Email',a.email,a.email_verified)}${contact('whatsapp','WhatsApp',a.phone,a.whatsapp_verified)}<p class="hint account-note">Verifikasi diperlukan untuk keamanan login dan pengajuan toko. Mengubah kontak membutuhkan alur verifikasi khusus.</p>`);
 const preferences=panel('Personalisasi tampilan',`<form data-form="preferences-update"><div class="form-grid"><div class="field wide"><label for="pref-theme">Tema aplikasi</label><select name="theme" id="pref-theme"><option value="light" ${u.theme==='light'?'selected':''}>Terang</option><option value="dark" ${u.theme==='dark'?'selected':''}>Gelap</option><option value="system" ${u.theme==='system'?'selected':''}>Ikuti pengaturan perangkat</option></select></div></div><h3 class="settings-subtitle">Preferensi notifikasi</h3><div class="flow"><label for="pref-email">Informasi melalui Email</label><input type="checkbox" id="pref-email" name="emailNotifications" ${u.email_notifications!==false?'checked':''}></div><div class="flow"><label for="pref-order">Kabar perubahan status pesanan</label><input type="checkbox" id="pref-order" name="orderNotifications" ${u.order_notifications!==false?'checked':''}></div><p class="hint">Pilihan tersimpan di database. Pengiriman notifikasi otomatis memerlukan layanan notifikasi yang aktif.</p><button class="btn primary" type="submit">Simpan preferensi</button></form>`);
 const shortcut=(key,title,description)=>`<a class="account-shortcut" href="#${key}">${ico(key)}<span><strong>${title}</strong><small>${description}</small></span><span class="shortcut-arrow">→</span></a>`;
 const activity=panel('Akses cepat aktivitas akun',`<div class="account-shortcuts">${shortcut('orders','Pesanan saya','Pantau status dan riwayat transaksi')}${shortcut('addresses','Alamat pengiriman','Kelola penerima dan lokasi pengiriman')}${shortcut('wishlist','Favorit saya','Produk yang telah disimpan')}${role()==='seller'?shortcut('sellerShop','Toko saya','Kelola informasi toko'):role()==='owner'?shortcut('ownerHome','Panel Owner','Ringkasan dan kontrol marketplace'):shortcut('apply','Mulai berjualan','Ajukan toko setelah verifikasi')}</div><div class="notice">Lihat ringkasan aktivitas dan kelola kebutuhan akun pada menu di atas.</div>`);
 const date=a.created_at?fmt(a.created_at):'—';
 const contacts=[a.email_verified?'Email terverifikasi':'Email belum terverifikasi',a.whatsapp_verified?'WhatsApp terverifikasi':'WhatsApp belum terverifikasi'];
 return heading('Pusat akun','Kelola identitas, keamanan, preferensi, dan aktivitas belanja dari satu halaman.')+`<section class="account-hero account-hero-v46"><div class="account-identity">${avatarMarkup('account-avatar')}<div class="account-identity-copy"><span class="eyebrow">AKUN KLIKCHART</span><strong>${E(u.display_name?.trim()||a.username||who())}</strong><small>@${E(a.username||who())} · ${E(roleLabel())}</small></div></div><div class="account-hero-stats"><span><small>Bergabung</small><b>${E(date)}</b></span><span><small>Status akun</small><b>${a.signup_verified?'Aktif':'Perlu verifikasi'}</b></span></div></section><div class="account-mini-status"><span class="${a.email_verified?'ok':'todo'}">${a.email_verified?'✓':'!'} ${contacts[0]}</span><span class="${a.whatsapp_verified?'ok':'todo'}">${a.whatsapp_verified?'✓':'!'} ${contacts[1]}</span>${(!a.email_verified||!a.whatsapp_verified)?`<button class="account-verify-cta" type="button" data-action="account-shortcut:security">Lengkapi verifikasi <span aria-hidden="true">→</span></button>`:''}</div><div class="account-layout-v46"><div class="account-primary">${tabsHtml}<section id="account-panel" role="tabpanel" aria-labelledby="account-tab-${S.accountTab}" class="account-main">${S.accountTab==='security'?security:S.accountTab==='preferences'?preferences:S.accountTab==='activity'?activity:info}</section>${role()==='buyer'&&S.accountTab==='info'?`<div class="account-seller-link"><div><strong>Punya produk untuk dijual?</strong><p>Ajukan toko dan mulai berjualan setelah disetujui pengelola.</p></div><a href="#apply" class="btn primary">Buka toko ↗</a></div>`:''}</div><aside class="account-side-v46" aria-label="Informasi akun"><div class="account-side-card"><h3>Detail akun</h3><dl><dt>Username</dt><dd>@${E(a.username||'—')}</dd><dt>Email</dt><dd>${E(a.email||'—')}</dd><dt>WhatsApp</dt><dd>${E(a.phone||'—')}</dd><dt>Peran</dt><dd>${E(roleLabel())}</dd><dt>Terdaftar</dt><dd>${E(date)}</dd></dl></div><div class="account-side-card account-side-help"><strong>Butuh bantuan?</strong><p>Untuk perubahan email atau nomor, gunakan prosedur verifikasi agar akun tetap aman.</p><a href="#account" data-action="account-shortcut:security">Lihat keamanan akun →</a></div></aside></div>`;
}
function ownerUsers(){const d=S.data.users||{};return heading('Direktori Pengguna','Daftar akun marketplace, dengan status verifikasi dan peran dari database.')+panel('Pengguna terdaftar',`<p class="hint">${Number(d.total||0)} akun · halaman ${d.page||1} · 20 akun per halaman. Peran tidak bisa diubah oleh pembeli.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Nama pengguna</th><th>Email</th><th>Peran</th><th>Email OTP</th><th>WhatsApp OTP</th></tr></thead><tbody>${(d.items||[]).map(x=>`<tr><td>${E(x.username||'—')}</td><td>${E(x.email||'—')}</td><td>${E(x.role||'buyer')}</td><td>${x.email_verified?badge('active'):badge('pending')}</td><td>${x.whatsapp_verified?badge('active'):badge('pending')}</td></tr>`).join('')}</tbody></table></div><div class="tools" style="margin-top:20px">${btn('← Sebelumnya','users-prev','small')}<span class="hint">${d.page||1}</span>${btn('Berikutnya →','users-next','small')}</div>`)}
function ownerSettings(){const a=S.data.site?.settings||S.site||{};return heading('Pengaturan Marketplace','Kendalikan identitas toko, pengumuman, dan ongkir checkout COD.')+`<div class="split">${panel('Identitas & operasional',`<form data-form="owner-settings"><div class="field"><label for="own-name">Nama marketplace</label><input id="own-name" name="storefrontName" maxlength="60" required value="${E(a.storefront_name||'Klikchart')}"></div><div class="field"><label for="own-announcement">Pengumuman untuk pembeli</label><textarea id="own-announcement" name="announcement" maxlength="220">${E(a.announcement||'')}</textarea></div><div class="field"><label for="own-support">Email bantuan</label><input id="own-support" type="email" name="supportEmail" value="${E(a.support_email||'')}"></div><div class="field"><label for="own-shipping">Ongkir tetap per toko (Rp)</label><input id="own-shipping" type="number" min="0" max="10000000" step="1000" name="shippingFee" required value="${Number(a.shipping_fee??15000)}"></div><button class="btn primary" type="submit">Simpan pengaturan marketplace</button></form>`)}${panel('Kontrol Owner',`<div class="flow"><div><strong>Persetujuan penjual</strong><p class="hint">Akses berjualan hanya setelah kedua kontak terverifikasi dan disetujui Owner.</p></div>${btn('Kelola','go:ownerApplications','small')}</div><div class="flow"><div><strong>Moderasi produk</strong><p class="hint">Arsipkan produk yang tidak sesuai aturan.</p></div>${btn('Kelola','go:ownerProducts','small')}</div><div class="flow"><div><strong>Akun dan keamanan</strong><p class="hint">Periksa akun, lalu ubah kata sandi melalui Akun & Pengaturan.</p></div>${btn('Buka','go:account','small')}</div><div class="notice warn">Ongkir di sini berlaku untuk pesanan baru. Pembayaran online, kurir otomatis dan refund tetap membutuhkan integrasi pihak ketiga.</div>` )}</div>`}
function render(){let inner='';const v=S.view;try{inner=v==='account'?account():v==='ownerUsers'?ownerUsers():v==='ownerSettings'?ownerSettings():v==='home'?home():v==='shop'?shop():v==='product'?productDetail():v==='cart'?cart():v==='wishlist'?wishlist():v==='addresses'?addresses():v==='orders'?orders():v==='apply'?apply():v==='sellerHome'?sellerHome():v==='sellerProducts'?sellerProducts():v==='sellerOrders'?orders('seller'):v==='sellerShop'?sellerShop():v==='ownerHome'?ownerHome():v==='ownerApplications'?ownerApps():v==='ownerShops'?ownerShops():v==='ownerProducts'?ownerProducts():v==='ownerOrders'?orders('owner'):v==='categories'?categoryAdmin():home();}catch(e){inner=heading('Ada kendala','Coba buka kembali halaman.')+`<div class="notice error">${E(msg(e))}</div>`}flash(inner)}
function wire(){document.getElementById('menu')?.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.toggle('open');document.getElementById('backdrop')?.classList.toggle('open')});document.getElementById('backdrop')?.addEventListener('click',()=>{document.getElementById('sidebar')?.classList.remove('open');document.getElementById('backdrop')?.classList.remove('open')});document.documentElement.dataset.theme=S.theme==='system'?(window.matchMedia?.('(prefers-color-scheme:dark)').matches?'dark':'light'):S.theme;const q=document.getElementById('global-q');q?.addEventListener('keydown',e=>{if(e.key==='Enter'){S.q=q.value.trim();S.page=1;location.hash='#home';if(S.view==='home')load()}});document.getElementById('cat-filter')?.addEventListener('change',e=>{S.category=e.target.value;S.page=1;load()});document.getElementById('sort-filter')?.addEventListener('change',e=>{S.sort=e.target.value;S.page=1;load()})}
function go(v){const hash='#'+v+(v==='product'&&S.productId?'/'+S.productId:v==='shop'&&S.shopId?'/'+S.shopId:'');if(location.hash!==hash){location.hash=hash;}else{S.view=v;load();}}
function routeFromHash(){const [route,routeId]=location.hash.slice(1).split('/');if(route==='product')S.productId=routeId||null;if(route==='shop')S.shopId=routeId||null;
 if(['profile','security','preferences','activity'].includes(route)){S.accountTab=route==='security'?'security':route==='preferences'?'preferences':route==='activity'?'activity':'info';location.hash='#account';return;}
 let next=names[route]?route:start();if((next==='product'&&!S.productId)||(next==='shop'&&!S.shopId))next='home';
 if(!isLogged()&&!['home','product','shop'].includes(next))next='home';
 if(role()==='buyer'&&next.startsWith('seller'))next='home';
 if(role()!=='owner'&&next.startsWith('owner'))next=start();
 if(role()!=='buyer'&&next==='apply')next=start();
 const viewChanged=S.view!==next;S.view=next;if(viewChanged){window.scrollTo({top:0,behavior:'instant'});}load();}
async function refresh(){const [me,site,cats]=await Promise.all([api('me').catch(()=>null),api('site-settings').catch(()=>({settings:null})),api('categories').catch(()=>({items:[]}))]);S.me=me;S.site=site.settings;S.categories=cats.items;routeFromHash();}
function productDialog(p={}){
 S.editId=p.id||null;
 const images=(Array.isArray(p.images)?p.images:(p.image_url?[p.image_url]:[])).filter(Boolean);
 formDialog(p.id?'Edit produk':'Produk baru','product-save',[
 ['name','Nama produk','text',p.name||'',true],['description','Deskripsi detail produk','textarea',p.description||'',true],
 ['price','Harga (Rp)','number',p.price||10000,false],['stock','Jumlah stok','number',p.stock??1,false],
 ['categoryId','Kategori','select',p.category_id||S.categories[0]?.id||'',false,S.categories.map(c=>[c.id,c.name])],
 ['status','Status penayangan','select',p.status||'draft',false,[['draft','Draft'],['published','Tayang'],['archived','Arsipkan']]]
 ],'Simpan produk');
 const f=document.getElementById('dialog-form');const footer=f.querySelector('.dialog-footer');
 footer.insertAdjacentHTML('beforebegin',`<div class="field wide upload-section"><label for="seller-photos">Foto produk (maksimal 6 foto, PNG/JPEG/WebP, maks. 2 MB per foto)</label><input id="seller-photos" type="file" accept="image/png,image/jpeg,image/webp" multiple><input type="hidden" name="images" id="product-images-json" value="${E(JSON.stringify(images))}"><div class="photo-previews" id="seller-photo-list"></div><div class="hint">Foto disimpan melalui Supabase Storage, bukan URL eksternal. Unggah foto terlebih dahulu, lalu simpan produk.</div></div>`);
 refreshPhotoPreviews();
}
function refreshPhotoPreviews(){const box=document.getElementById('seller-photo-list'),input=document.getElementById('product-images-json');if(!box||!input)return;let images=[];try{images=JSON.parse(input.value)}catch{}box.innerHTML=images.map((url,i)=>`<div class="seller-photo-thumb"><img src="${E(url)}" alt="Foto ${i+1}"><button type="button" data-action="remove-photo:${i}" aria-label="Hapus foto">✕</button></div>`).join('');}
async function uploadPhoto(file){if(file.size>2*1024*1024)throw {code:'IMAGE_SIZE_INVALID'};if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw {code:'IMAGE_TYPE_INVALID'};
 const r=await fetch('/api/market/seller/product-photo',{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type,'X-Klikchart-Request':'1'},body:file});const j=await r.json();if(!r.ok||!j.ok)throw {code:j?.error?.code||'IMAGE_UPLOAD_FAILED'};return j.data.url;
}
document.addEventListener('change',async e=>{if(e.target?.id!=='seller-photos')return;const input=e.target,field=document.getElementById('product-images-json'),box=document.getElementById('seller-photo-list');if(!field)return;let images=JSON.parse(field.value||'[]');const files=[...input.files];if(images.length+files.length>6){toast('Maksimal 6 foto per produk.');input.value='';return}
 input.disabled=true;const submit=document.querySelector('#dialog-form [type="submit"]');if(submit)submit.disabled=true;box.insertAdjacentHTML('beforeend','<span id="upload-hint">Mengunggah foto…</span>');
 try{for(const file of files){const url=await uploadPhoto(file);images.push(url);field.value=JSON.stringify(images);refreshPhotoPreviews()}toast('Foto berhasil diunggah. Simpan produk untuk menerapkan perubahan.')}catch(err){toast(msg(err));}finally{input.disabled=false;if(submit)submit.disabled=false;input.value='';document.getElementById('upload-hint')?.remove()}
});
function openAddress(a={}){
 S.editAddressId=a.id||null;
 formDialog(a.id?'Edit alamat pengiriman':'Tambah alamat pengiriman',a.id?'address-edit':'address-add',[
 ['recipient','Nama lengkap penerima','text',a.recipient||'',true],
 ['phone','Nomor telepon penerima','text',a.phone||'',false],
 ['province','Provinsi','text',a.province||'',false],
 ['city','Kota / Kabupaten','text',a.city||'',false],
 ['postalCode','Kode pos','text',a.postal_code||'',false],
 ['address','Alamat lengkap','textarea',a.address||'',true]
 ],a.id?'Simpan perubahan':'Simpan alamat');
 const form=document.getElementById('dialog-form');if(!form)return;
 form.classList.add('kc-address-form');
 form.insertAdjacentHTML('afterbegin','<div class="kc-address-guide">'+ico('addresses')+'<span>Lengkapi penerima, nomor telepon, wilayah, dan alamat. Alamat ini digunakan ketika checkout COD.</span></div>');
 const hints={recipient:'Nama orang yang menerima paket.',phone:'Nomor aktif yang dapat dihubungi.',province:'Pilih dari saran atau tulis nama provinsi.',city:'Kota atau kabupaten sesuai alamat.',postalCode:'Lima angka kode pos.',address:'Nama jalan, nomor rumah, RT/RW, kelurahan, kecamatan, dan patokan.'};
 const placeholders={recipient:'Nama penerima',phone:'081234567890',province:'Jawa Barat',city:'Kabupaten Cirebon',postalCode:'45611',address:'Jl. Merdeka No. 12, RT 02/RW 05, Kelurahan ..., Kecamatan ...'};
 for(const [name,hint] of Object.entries(hints)){const field=form.elements.namedItem(name);if(!field)continue;field.placeholder=placeholders[name];const parent=field.closest('.field');if(parent){const small=document.createElement('small');small.textContent=hint;parent.appendChild(small)}}
 const phone=form.elements.namedItem('phone');if(phone){phone.setAttribute('inputmode','tel');phone.setAttribute('autocomplete','tel');phone.setAttribute('minlength','9');phone.setAttribute('maxlength','25')}
 const postal=form.elements.namedItem('postalCode');if(postal){postal.setAttribute('inputmode','numeric');postal.setAttribute('pattern','[0-9]{5}');postal.setAttribute('maxlength','5');postal.setAttribute('autocomplete','postal-code')}
 const recipient=form.elements.namedItem('recipient');if(recipient)recipient.setAttribute('autocomplete','name');
 const street=form.elements.namedItem('address');if(street){street.setAttribute('minlength','10');street.setAttribute('maxlength','400');street.setAttribute('autocomplete','street-address')}
 const city=form.elements.namedItem('city');if(city)city.setAttribute('autocomplete','address-level2');
 const province=form.elements.namedItem('province');if(province){province.setAttribute('autocomplete','address-level1');province.setAttribute('list','kc-province-options');
 const list=document.createElement('datalist');list.id='kc-province-options';
 const provinces=['Aceh','Sumatera Utara','Sumatera Barat','Riau','Kepulauan Riau','Jambi','Sumatera Selatan','Kepulauan Bangka Belitung','Bengkulu','Lampung','Banten','DKI Jakarta','Jawa Barat','Jawa Tengah','DI Yogyakarta','Jawa Timur','Bali','Nusa Tenggara Barat','Nusa Tenggara Timur','Kalimantan Barat','Kalimantan Tengah','Kalimantan Selatan','Kalimantan Timur','Kalimantan Utara','Sulawesi Utara','Gorontalo','Sulawesi Tengah','Sulawesi Barat','Sulawesi Selatan','Sulawesi Tenggara','Maluku','Maluku Utara','Papua','Papua Barat','Papua Barat Daya','Papua Tengah','Papua Pegunungan','Papua Selatan'];
 for(const name of provinces){const option=document.createElement('option');option.value=name;list.appendChild(option)}form.appendChild(list);
 }
}
async function checkoutDialog(){
 const [addressData,cartData]=await Promise.all([api('addresses'),api('cart')]);
 const addresses=addressData?.items||[],items=(cartData?.items||[]).filter(c=>c.market_products);
 if(!items.length){toast('Keranjang kosong. Tambahkan produk dahulu.');go('home');return}
 if(items.some(c=>c.market_products.status!=='published'||c.market_products.market_shops?.status!=='active'||Number(c.market_products.stock)<Number(c.quantity))){toast('Ada produk yang tidak tersedia atau stoknya berubah. Periksa keranjang.');go('cart');return}
 if(!addresses.length){toast('Tambahkan alamat pengiriman terlebih dahulu.');go('addresses');return}
 const sub=items.reduce((n,c)=>n+Number(c.market_products.price)*Number(c.quantity),0);
 const stores=new Set(items.map(c=>c.market_products.shop_id)).size;
 const shipping=stores*Number(S.site?.shipping_fee??15000);
 const rows=items.map(c=>`<div class="checkout-item"><span>${E(c.market_products.name)} <small>×${Number(c.quantity)}</small></span><strong>${money(Number(c.market_products.price)*Number(c.quantity))}</strong></div>`).join('');
 dialog('Konfirmasi pesanan COD',`<p class="hint">Pastikan produk dan alamat sudah benar sebelum memesan.</p><div class="checkout-summary">${rows}<div class="checkout-item"><span>Subtotal</span><strong>${money(sub)}</strong></div><div class="checkout-item"><span>Estimasi ongkir (${stores} toko)</span><strong>${money(shipping)}</strong></div><div class="checkout-item checkout-total"><span>Estimasi total COD</span><strong>${money(sub+shipping)}</strong></div></div><div class="notice warn">Pembayaran dilakukan kepada penjual saat barang diterima. Pengiriman dan ongkir masih dikelola secara manual; total akhir akan dihitung ulang oleh server.</div><form id="dialog-form" data-form="checkout"><div class="field"><label for="f-addressId">Alamat penerima</label><select id="f-addressId" name="addressId" required>${addresses.map(v=>`<option value="${E(v.id)}">${E(v.recipient)} — ${E(v.address)}, ${E(v.city)}</option>`).join('')}</select></div><label class="checkout-confirm"><input type="checkbox" name="confirmed" required><span>Saya sudah memeriksa produk, alamat, dan metode COD.</span></label><div class="dialog-footer"><button class="btn" type="button" data-action="dialog-close">Kembali</button><button class="btn primary" type="submit">Buat pesanan COD</button></div></form>`);
}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();if(S.busy)return;S.busy=true;const b=f.querySelector('[type="submit"]');if(b)b.disabled=true;
 try{const d=formData(f),kind=f.dataset.form;let message='Berhasil disimpan.';let navigate=null;
 if(kind==='contact-verify'){if(!S.pendingContact)throw Error('OTP_INVALID');await accountAPI(S.pendingContact.channel+'/verify',{challengeId:S.pendingContact.challengeId,code:d.code});S.pendingContact=null;S.me=await api('me');message='Kontak berhasil diaktifkan.';}
 else if(kind==='profile-update'){await api('profile',d);[S.me,S.profileSnapshot]=await Promise.all([api('me'),api('profile')]);refreshAccountChrome();message='Profil berhasil diperbarui.';}
 else if(kind==='password-change'){await api('password/change',d);message='Kata sandi berhasil diubah. Silakan login lagi.';toast(message);location.assign('/login');return;}
 else if(kind==='preferences-update'){await api('preferences',{theme:d.theme,emailNotifications:f.elements.emailNotifications.checked,orderNotifications:f.elements.orderNotifications.checked});S.theme=d.theme;message='Preferensi disimpan.';}
 else if(kind==='owner-settings'){await api('owner/site-settings',{storefrontName:d.storefrontName,announcement:d.announcement,supportEmail:d.supportEmail,shippingFee:Number(d.shippingFee)});S.site=(await api('site-settings')).settings;message='Pengaturan web diperbarui.';}
 else if(kind==='address-edit'){await api('addresses/'+S.editAddressId,d);message='Alamat diperbarui.';}
 else if(kind==='seller-apply'){await api('seller/apply',d);message='Pengajuan penjual berhasil dikirim.';S.me=await api('me')}
 else if(kind==='product-save'){if(!S.editId)S.sellerPage=1;await api('seller/products'+(S.editId?'/'+S.editId:''),{...d,images:JSON.parse(d.images||'[]'),price:Number(d.price),stock:Number(d.stock),categoryId:Number(d.categoryId)});message='Produk disimpan di database.'}
 else if(kind==='shop-edit'){await api('seller/shop',d);S.me=await api('me');message='Profil toko diperbarui.'}
 else if(kind==='address-add'){await api('addresses',d);message='Alamat ditambahkan.'}
 else if(kind==='checkout'){const result=await api('checkout',d);message=`${result.count} pesanan COD berhasil dibuat.`;navigate='orders'}
 else if(kind==='category-new'){await api('owner/categories',d);S.categories=(await api('categories')).items;message='Kategori ditambahkan.'}
 else if(kind==='review'){await api('reviews',{...d,rating:Number(d.rating)});message='Ulasan berhasil dikirim.'}
 closeDialog();toast(message);navigate?go(navigate):load();
 }catch(err){toast(msg(err));}finally{S.busy=false;if(b)b.disabled=false;}});
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const act=target.dataset.action;try{
 if(act==='profile-menu-toggle'){const popup=target.parentElement?.querySelector('.profile-menu');const visible=popup&&!popup.hidden;document.querySelectorAll('.profile-menu').forEach(p=>p.hidden=true);document.querySelectorAll('.profile-menu-toggle').forEach(b=>b.setAttribute('aria-expanded','false'));if(popup){popup.hidden=visible;target.setAttribute('aria-expanded',String(!visible))}return}
 if(act.startsWith('account-shortcut:')){S.accountTab=act.split(':')[1];document.querySelectorAll('.profile-menu').forEach(p=>p.hidden=true);go('account');return}
 if(act.startsWith('password-visibility:')){const el=document.getElementById(act.split(':')[1]);if(!el)return;const show=el.type==='password';el.type=show?'text':'password';target.setAttribute('aria-pressed',String(show));const label=target.querySelector('span');if(label)label.textContent=show?'Sembunyikan':'Tampilkan';target.setAttribute('aria-label',(show?'Sembunyikan ':'Tampilkan ')+(el.labels?.[0]?.textContent?.trim()||'kata sandi'));return}
 if(act==='account-contact'){S.accountTab='security';go('account');return}
 if(act.startsWith('account-tab:')){S.accountTab=act.split(':')[1];render();document.getElementById('account-tab-'+S.accountTab)?.focus({preventScroll:true});return}
 if(act.startsWith('contact-send:')){const channel=act.split(':')[1];if(!['email','whatsapp'].includes(channel))return;const result=await accountAPI(channel+'/send',{locale:'id'});S.pendingContact={channel,challengeId:result.challengeId};const masked=channel==='email'?result.emailMasked:result.phoneMasked;dialog('Aktifkan '+(channel==='email'?'Email':'WhatsApp'),`<div class="hint">Kami mengirim kode 6 digit ke ${E(masked||'kontak terdaftar')}. Berlaku selama 5 menit.</div><form data-form="contact-verify" class="contact-otp-form"><div class="field"><label for="contact-code">Kode verifikasi</label><input id="contact-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" minlength="6" required placeholder="000000"></div><div class="dialog-footer"><button type="button" class="btn" data-action="dialog-close">Tutup</button><button type="submit" class="btn primary">Aktifkan kontak</button></div></form>`);return}
 if(act==='dialog-close'){closeDialog();return}
 if(act==='seller-products-prev'){S.sellerPage=Math.max(1,S.sellerPage-1);await load();return}
 if(act==='seller-products-next'){if(S.sellerPage*20<(S.data.sellerProducts?.total||0)){S.sellerPage++;await load()}return}
 if(act==='owner-products-prev'){S.ownerProductPage=Math.max(1,S.ownerProductPage-1);await load();return}
 if(act==='owner-products-next'){if(S.ownerProductPage*20<(S.data.ownerProducts?.total||0)){S.ownerProductPage++;await load()}return}
 if(act==='orders-prev'){S.orderPage=Math.max(1,S.orderPage-1);await load();return}
 if(act==='orders-next'){S.orderPage++;await load();return}
 if(act==='reset-filters'){S.q='';S.category='';S.minPrice='';S.maxPrice='';S.page=1;go('home');return}
 if(act==='scroll-products'){document.getElementById('products-section')?.scrollIntoView({behavior:'smooth'});return}
 if(act==='apply-price'){const min=document.getElementById('min-price')?.value||'',max=document.getElementById('max-price')?.value||'';if(min&&max&&Number(min)>Number(max)){toast('Harga minimum tidak boleh lebih besar dari maksimum.');return}S.minPrice=min;S.maxPrice=max;S.page=1;await load();return}
 if(act.startsWith('category:')){S.category=act.split(':')[1]||'';S.page=1;go('home');return}
 if(act.startsWith('gallery:')){S.activePhoto=Number(act.split(':')[1])||0;render();return}
 if(act.startsWith('visit-shop:')){S.shopId=act.split(':')[1];S.page=1;go('shop');return}
 if(act.startsWith('remove-photo:')){const field=document.getElementById('product-images-json');if(!field)return;const imgs=JSON.parse(field.value||'[]');imgs.splice(Number(act.split(':')[1]),1);field.value=JSON.stringify(imgs);refreshPhotoPreviews();return}

 if(act==='reload'){await load();return}
 if(act.startsWith('go:')){go(act.slice(3));return}
 if(act==='prev'){S.page=Math.max(1,S.page-1);await load();return}
 if(act==='shops-prev'){S.shopPage=Math.max(1,S.shopPage-1);await load();return}
 if(act==='shops-next'){const d=S.data.shops||{};if((d.items||[]).length===20&&S.shopPage*20<(d.total||0)){S.shopPage++;await load()}return}
 if(act==='users-prev'){S.userPage=Math.max(1,S.userPage-1);await load();return}
 if(act==='users-next'){const d=S.data.users||{};if((d.items||[]).length===20&&S.userPage*20<(d.total||0)){S.userPage++;await load()}return}
 if(act==='next'){if((S.data.products?.items||[]).length===16){S.page++;await load()}return}
 if(act.startsWith('view-product:')){S.productId=act.split(':')[1];S.activePhoto=0;go('product');return}
 if(act.startsWith('wishlist-add:')){if(!isLogged()){location.assign('/login');return}await api('wishlist',{productId:act.split(':')[1],saved:true});toast('Disimpan ke Favorit.');return}
 if(act.startsWith('wishlist-remove:')){await api('wishlist',{productId:act.split(':')[1],saved:false});toast('Dihapus dari Favorit.');await load();return}
 if(act.startsWith('review:')){const productId=act.split(':')[1];formDialog('Beri ulasan produk','review',[['productId','ID Produk','text',productId,true],['rating','Rating 1–5','select','5',false,[[5,'★★★★★ (5)'],[4,'★★★★☆ (4)'],[3,'★★★☆☆ (3)'],[2,'★★☆☆☆ (2)'],[1,'★☆☆☆☆ (1)']]],['comment','Pengalaman belanja','textarea','',true]],'Kirim ulasan');const f=document.getElementById('f-productId');if(f)f.readOnly=true;return}
 if(act.startsWith('cod:')){const id=act.split(':')[1];if(!(await confirmAction('Catat penerimaan COD','Pastikan pembayaran tunai sudah diterima. Catatan ini bukan verifikasi dari payment gateway.',{confirmLabel:'Catat pembayaran'})))return;await api('orders/'+id+'/report-cod',{});toast('Penerimaan COD dicatat oleh penjual.');await load();return}
 if(act.startsWith('cart-add:')){if(!isLogged()){location.assign('/login');return}const id=act.split(':')[1];const c=await api('cart');const old=c.items.find(x=>x.product_id===id)?.quantity||0;await api('cart',{productId:id,quantity:old+1});toast('Produk ditambahkan ke keranjang.');return}
 if(act.startsWith('cart-qty:')){const [,productId,qty]=act.split(':');await api('cart',{productId,quantity:Number(qty)});toast('Keranjang diperbarui');await load();return}
 if(act==='checkout'){await checkoutDialog();return}
 if(act.startsWith('address-edit:')){const a=S.data.addresses?.items?.find(x=>x.id===act.slice(13));if(a)openAddress(a);return}
 if(act==='address-new'){openAddress();return}
 if(act.startsWith('address-delete:')){if(!(await confirmAction('Hapus alamat','Alamat yang dihapus tidak dapat dipilih untuk pesanan baru.',{confirmLabel:'Hapus alamat',danger:true})))return;await api('addresses/'+act.slice('address-delete:'.length)+'/delete',{});toast('Alamat dihapus');await load();return}
 if(act.startsWith('order:')){const [,id,status]=act.split(':');const answer=await confirmAction('Ubah status pesanan','Status pesanan akan diubah menjadi '+(status==='shipped'?'Dikirim':status==='packed'?'Dikemas':status==='accepted'?'Diterima':status==='delivered'?'Selesai':status==='canceled'?'Dibatalkan':status)+'.',{confirmLabel:'Simpan status',fieldLabel:status==='shipped'?'Nomor resi / catatan pengiriman (manual)':'',required:status==='shipped'});if(!answer)return;const tracking=answer.note;await api('orders/'+id+'/status',{status,tracking});toast('Status pesanan diperbarui.');await load();return}
 if(act==='product-new'){productDialog();return}
 if(act.startsWith('product-edit:')){const p=S.data.sellerProducts?.items?.find(x=>x.id===act.split(':')[1]);if(p)productDialog(p);return}
 if(act.startsWith('application:')){const [,id,status]=act.split(':');const answer=await confirmAction(status==='approved'?'Setujui pengajuan toko':'Tolak pengajuan toko','Periksa informasi calon penjual sebelum menyimpan keputusan.',{confirmLabel:status==='approved'?'Setujui toko':'Tolak pengajuan',fieldLabel:status==='approved'?'Catatan persetujuan (opsional)':'Alasan penolakan',required:status==='rejected',danger:status==='rejected'});if(!answer)return;const note=answer.note;await api('owner/applications/'+id+'/decision',{status,note});toast('Keputusan tersimpan.');await load();return}
 if(act.startsWith('shop-status:')){const [,id,status]=act.split(':');if(!(await confirmAction('Ubah status toko','Perubahan status dapat memengaruhi produk dan pesanan toko.',{confirmLabel:'Simpan status',danger:status==='suspended'})))return;await api('owner/shops/'+id+'/status',{status});toast('Status toko tersimpan.');await load();return}
 if(act.startsWith('mod-product:')){const [,id,status]=act.split(':');if(!(await confirmAction('Moderasi produk','Perubahan status produk akan langsung memengaruhi katalog penjualan.',{confirmLabel:'Terapkan moderasi',danger:status==='archived'})))return;await api('owner/products/'+id+'/status',{status});toast('Moderasi produk disimpan.');await load();return}
 if(act==='category-new'){formDialog('Kategori baru','category-new',[['name','Nama kategori','text','',true],['slug','Slug (huruf kecil dan tanda -)','text','',true]]);return}
 if(act==='logout'){const r=await fetch('/api/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Klikchart-Request':'1'},body:'{}'});if(r.ok){location.assign('/login')}else{toast('Gagal keluar dari akun. Coba lagi.')}return}
 }catch(err){toast(msg(err));}});
