document.addEventListener('input',e=>{if(e.target?.id!=='pf-avatarUrl'&&e.target?.id!=='pf-displayName')return;const parent=document.getElementById('profile-avatar-preview');if(!parent)return;const url=document.getElementById('pf-avatarUrl')?.value.trim()||'';const name=document.getElementById('pf-displayName')?.value.trim()||who();const valid=/^https:\/\/[^\s]+$/i.test(url)&&!/@/.test(url.split('/')[2]||'')&&url.length<=500;const img=parent.querySelector('img');if(img){if(valid)img.src=url;else img.remove()}else if(valid){const i=document.createElement('img');i.alt='';i.loading='lazy';i.decoding='async';i.src=url;parent.querySelector('.avatar')?.prepend(i)}const initial=parent.querySelector('.avatar-initial');if(initial)initial.textContent=(name[0]||'K').toUpperCase();});
