// Keep keyboard navigation inside an active modal; restore focus after closing.
document.addEventListener('keydown',event=>{
 if(event.key!=='Tab')return;
 const modal=document.getElementById('modal');if(!modal)return;
 const items=[...modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]):not([type=hidden]),select:not([disabled]),textarea:not([disabled])')].filter(el=>el.getClientRects().length);
 if(!items.length){event.preventDefault();modal.querySelector('.dialog')?.focus();return;}
 const first=items[0],last=items[items.length-1];
 if(event.shiftKey && (document.activeElement===first||!modal.contains(document.activeElement))){event.preventDefault();last.focus()}
 else if(!event.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){event.preventDefault();first.focus()}
});
// Display a stable fallback when a remote product photo is unavailable.
document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement && image.closest('.product-image-frame')){image.hidden=true;image.closest('.product-image-frame')?.classList.add('image-failed')}},true);
